PNE_st.name='PNE'; 
PNE_st.lat=18.52;
PNE_st.lon=73.86;
PNE_st.alt=0000;
PNE_st.env='Con';
PNE_st.footp='U';
%%
% data imported via the import tool from matlab
 PNE_rd_h = importfile_AE_India("C:\github_trend\raw_data\Aethalometer_India\Aethalometer\PNE_2016-2026_Hour.csv", [2, Inf]);
PNE_rd_h.Properties.DimensionNames{1}='Time';
PNE_rd_h.Properties.VariableNames{2}='Ba1_A';
PNE_rd_h.Properties.VariableNames{3}='Ba2_A';
PNE_rd_h.Properties.VariableNames{4}='Ba3_A';
PNE_rd_h.Properties.VariableNames{5}='Ba4_A';
PNE_rd_h.Properties.VariableNames{6}='Ba5_A';
PNE_rd_h.Properties.VariableNames{7}='Ba6_A';
PNE_rd_h.Properties.VariableNames{8}='Ba7_A';
names_rd=fieldnames(PNE_rd_h);
%%
% data imported via the import tool from matlab
 PNE_rd_h2 = importfile_AE_India("C:\github_trend\raw_data\Aethalometer_India\PNE_2016-2026_Hour.csv", [2, Inf]);
PNE_rd_h2.Properties.DimensionNames{1}='Time';
PNE_rd_h2.Properties.VariableNames{2}='Ba1_A';
PNE_rd_h2.Properties.VariableNames{3}='Ba2_A';
PNE_rd_h2.Properties.VariableNames{4}='Ba3_A';
PNE_rd_h2.Properties.VariableNames{5}='Ba4_A';
PNE_rd_h2.Properties.VariableNames{6}='Ba5_A';
PNE_rd_h2.Properties.VariableNames{7}='Ba6_A';
PNE_rd_h2.Properties.VariableNames{8}='Ba7_A';
names_rd=fieldnames(PNE_rd_h);
%%
PNE_rd=retime(PNE_rd_h,'daily',@nanmedian);
PNE_rd2=retime(PNE_rd_h2,'daily',@nanmedian);
%%
datevec(PNE_rd.Time(1)) % begin in 2016,  %[output:7a3f5d0a]
datevec(PNE_rd.Time(end)) % end in 2021 February too short %[output:0c280ed0]
plotFigControl(PNE_rd2,PNE_st.name);  %[output:7030742d] %[output:92f916c9] %[output:8a3db4cb] %[output:0941217c] %[output:81f161b9] %[output:7911ff20] %[output:977cd030] %[output:04cba172]
%%
% make whole PNE data
P1=timerange('2016-01-01','2024-04-29');
P2=timerange('2024-04-29','2025-08-01');
Ca3=startsWith(names_rd,{'Ba'}) & contains(names_rd,{'_A'});
names_abs=names_rd(Ca3);
for i=1:length(names_abs)
PNE_rd2.(names_abs{i})(P1)=PNE_rd.(names_abs{i})(P1);
end
%%
% make abs
sigma=[18.47 14.54 13.14 11.58 10.35 7.77 7.19]; %for the 7 wavelengths with an exponent of -1
PNE_rd2.Ba1_A=PNE_rd2.Ba1_A .*sigma(1);
PNE_rd2.Ba2_A=PNE_rd2.Ba2_A .*sigma(2);
PNE_rd2.Ba3_A=PNE_rd2.Ba3_A .*sigma(3);
PNE_rd2.Ba4_A=PNE_rd2.Ba4_A .*sigma(4);
PNE_rd2.Ba5_A=PNE_rd2.Ba5_A .*sigma(5);
PNE_rd2.Ba6_A=PNE_rd2.Ba6_A .*sigma(6);
PNE_rd2.Ba7_A=PNE_rd2.Ba7_A .*sigma(7);

%%
lambdaAE7=[370 470 520 590 660 880 950];
%compute abs exp
Ca3=startsWith(names_rd,{'Ba'}) & contains(names_rd,{'_A'});
names_abs=names_rd(Ca3);
PNE_cal=compute_exp_D(PNE_rd2,names_abs,lambdaAE7); %[output:644c8cd6] %[output:255a60ee] %[output:2f43a2a3]
plotFigControl_cal(PNE_cal,PNE_st.name); %[output:597337b1] %[output:9ff39bcc] %[output:841f7452]
%%
%HOMOGENEITY

break_PNE_abs_BP=change_point_analysis_Def(PNE_rd2,names_abs,0.05,'PNE','Absorption'); %[output:7046d319] %[output:16f55a3d] %[output:86bed013] %[output:6a7f5e81] %[output:8521bdd7] %[output:314f2656]
T_PNE_abs_BP=make_table_breakpoints_def(break_PNE_abs_BP);

names_expA={'expA_bgAE','expA_brAE','expA_grAE','expA_fit'} %[output:518d2f75]
break_PNE_expA_BP=change_point_analysis_Def(PNE_cal,names_expA,0.05,'PNE','Absorption exponent'); %[output:7311d791] %[output:604b6dfb] %[output:7f7c2edc] %[output:779b5d0e]
T_PNE_expA_BP=make_table_breakpoints_def(break_PNE_expA_BP); %[output:8e4a72ad] %[output:55702315] %[output:5deaeaa6] %[output:447a6cc9] %[output:5d97dd23] %[output:236d1e91]
%%
PNE_tr=outerjoin(PNE_rd2, PNE_cal);
PNE_tr.y=year(PNE_tr.Time);
% begin at the beginning of a year: 2016 
%end: 2025
P=timerange('2016-01-01','2025-01-01');
PNE_tr=PNE_tr(P,:);

