% % N=names(c);
% % for i=1:length(N)
% %     PNE_tr.(N{i})=[];
% % end

%
PNE_tr.Ba1_A=[];
PNE_tr.Ba2_A=[];
PNE_tr.Ba4_A=[];
PNE_tr.Ba5_A=[];
PNE_tr.Ba6_A=[];
PNE_tr.Ba7_A=[];

PNE_tr.BB=[];

PNE_tr.expA_bgAE=[];
PNE_tr.expA_brAE=[];
PNE_tr.expA_grAE=[];
%%
% % % data in Mm-1
% % PNE_tr.Ba3_A=PNE_tr.Ba3_A.*1e6;
%%
[PNE_result_MK,PNE_result_LMSlog,PNE_result_LMSlin]=all_trend_STN(PNE_tr,PNE_st); %[output:20405b6e] %[output:361be094] %[output:4bf13d9f] %[output:249feffb] %[output:394fb953] %[output:3c51b0a1] %[output:888e7483] %[output:722484bc] %[output:03263073] %[output:2a3cd227] %[output:38c10fa3] %[output:9f9f7e49] %[output:7c669d5a] %[output:7bd75486] %[output:4eabc371] %[output:8a2201c1] %[output:31af009f] %[output:8219b8c8] %[output:1bd72aa5] %[output:1cbe093c] %[output:10e1341d]

writetable(PNE_result_MK,'PNE_res_MK.txt'); %, 'delimiter',',' )
writetable(PNE_result_LMSlog,'PNE_res_LMSlog.txt'); 
writetable(PNE_result_LMSlin,'PNE_res_LMSlin.txt'); 
